package com.ruoyi.web.controller.portal;
import java.util.Map; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.web.bind.annotation.*; import com.ruoyi.common.annotation.Anonymous; import com.ruoyi.common.core.controller.BaseController; import com.ruoyi.common.core.domain.AjaxResult; import com.ruoyi.framework.web.service.MpTokenService; import com.ruoyi.system.service.IYcMeetingAnalyticsService; import jakarta.servlet.http.HttpServletRequest;
@Anonymous @RestController @RequestMapping("/portal/meeting/event") public class PortalMeetingAnalyticsController extends BaseController { @Autowired private IYcMeetingAnalyticsService service; @Autowired private MpTokenService tokens; @PostMapping public AjaxResult record(@RequestBody Map<String,Object> body,HttpServletRequest req){service.record(Long.valueOf(String.valueOf(body.get("activityId"))),String.valueOf(body.get("entryId")),String.valueOf(body.get("eventType")),body.get("context") instanceof Map?(Map<String,Object>)body.get("context"):null,tokens.getLoginUser(req));return success();} }
